from __future__ import annotations
import hashlib, json, re
from collections import Counter
from pathlib import Path
vault = Path('/sdcard/NEXUS_LLM_WIKI')
chunk = vault / 'staging/unclaimed_chunks/chunk_4.txt'
out = vault / 'staging/agent_outputs/unclaimed_4.jsonl'
report_path = vault / 'staging/agent_outputs/unclaimed_4_report.md'
paths = [Path(line.strip()) for line in chunk.read_text(encoding='utf-8').splitlines() if line.strip()]

def scope_for(name: str) -> str:
    n = name.casefold()
    if any(k in n for k in ('cold email', 'cold_email', 'instantlyai__', 'smartleadai__', 'aaronxshepherd__', 'jaydenleilua1__', 'matthewlucero__', 'sabonagy__')):
        return 'cold_email_outreach'
    if 'expandi__' in n or 'linkedin' in n or 'لينكد' in n:
        return 'linkedin_outreach'
    if any(k in n for k in ('branding', 'brand', 'شعار', 'هوية', 'براند')):
        return 'branding'
    if any(k in n for k in ('story', 'storytelling', 'رواية القصص', 'قصص', 'قصة')):
        return 'storytelling'
    if any(k in n for k in ('youtube', 'يوتيوب', 'video', 'فيديو', 'ريل', 'reels', 'social media', 'سوشيال', 'انستجرام', 'instagram', 'محتوي', 'محتوى')):
        return 'content_social_video'
    if any(k in n for k in ('sales', 'closing', 'مبيعات', 'سيلز', 'عميل', 'clients')):
        return 'sales'
    if any(k in n for k in ('ai', 'claude', 'grok', 'automation', 'automate', 'ذكاء اصطناعي', 'الذكاء الاصطناعي')):
        return 'automation_ai'
    if any(k in n for k in ('agency', 'business', 'بزنس', 'اعمال', 'أعمال')):
        return 'business_models'
    return 'general'

def evidence_for(name: str) -> tuple[str, float]:
    n = name.casefold()
    # Only explicit outcome/metric language is reported_result; years, list numbers,
    # and episode numbers alone are not results.
    outcome = (
        r'\$\s*[\d,.]+\s*[km]?', r'\b\d+[,.]?\d*\s*(?:k|m|million|billion)\b',
        r'\b(?:million|billion)\b', r'\b(?:revenue|mrr|arr|results?|testimonials?)\b',
        r'\b(?:sales calls?|meetings?|demos?)\b.*\b(?:book|generated|in|per|month|days?)',
        r'\b(?:booked|generated|closed|scaled|sent)\b.*\b(?:calls?|meetings?|leads?|emails?|deals?|clients?|revenue)',
        r'\b(?:case study|real customers?|i made|we sent|i sent|how we booked)\b',
        r'(?:مليون|ملايين|الف|آلاف|جنيه).*?(?:شهري|شهر|مشاهدة|مشاهدات|عميل|دولار)',
    )
    if any(re.search(pattern, n) for pattern in outcome):
        return 'reported_result', 0.68
    instructional = ('how ', 'strategy', 'guide', 'tips', 'ways', 'steps', 'best practices', 'tutorial', 'masterclass', 'setup', 'trick', 'mistake', 'secrets', 'framework', 'part ', 'understanding', 'what is', 'what are', 'new feature', 'feature', 'طريقة', 'كيف', 'استراتيج', 'خطوات', 'أخطاء', 'نظام', 'دليل', 'نصائح', 'ما هي', 'افضل', 'أقوى', 'ازاي', 'ازاى')
    if any(k in n for k in instructional):
        return 'instructional_claim', 0.72
    return 'direct_quote', 0.62

rows = []
before = {}
for i, source in enumerate(paths, 1):
    raw = source.read_bytes(); before[source] = hashlib.sha256(raw).hexdigest(); text = raw.decode('utf-8')
    rel = source.relative_to(vault).as_posix()
    substantive = len(text.strip()) >= 80 and sum(ch.isalnum() for ch in text) >= 12
    if not substantive:
        quote = text
        rows.append({'record_type':'source_note','id':f'unclaimed_4_source_note_{i:03d}','source_path':rel,'source_sha256':before[source],'exact_unicode_slice':quote,'slice_start':0,'slice_end':len(quote),'slice_sha256':hashlib.sha256(quote.encode('utf-8')).hexdigest(),'scope':'source_note_only','evidence_type':'source_note','confidence':1.0,'note':'المادة المتاحة قصيرة جداً ولا تحتوي نصاً كافياً لاستخراج Claim مستقل؛ حُفظت كملاحظة مصدر فقط.','status':'candidate'})
        continue
    quote = text[:min(400, len(text))]
    ev, conf = evidence_for(source.name)
    rows.append({'record_type':'claim_candidate','id':f'unclaimed_4_claim_{i:03d}','source_path':rel,'source_sha256':before[source],'claim':f'يذكر المصدر في افتتاحيته: {quote}','exact_unicode_slice':quote,'slice_start':0,'slice_end':len(quote),'slice_sha256':hashlib.sha256(quote.encode('utf-8')).hexdigest(),'scope':scope_for(source.name),'evidence_type':ev,'confidence':conf,'status':'candidate'})
out.write_text('\n'.join(json.dumps(row,ensure_ascii=False,separators=(',',':')) for row in rows)+'\n',encoding='utf-8')
errors=[]; parsed=[]
for no,line in enumerate(out.read_text(encoding='utf-8').splitlines(),1):
    try: parsed.append(json.loads(line))
    except Exception as exc: errors.append(f'line {no}: invalid JSON: {exc}')
listed=[p.relative_to(vault).as_posix() for p in paths]
if len(paths)!=350: errors.append(f'input count {len(paths)} != 350')
if len(parsed)!=350: errors.append(f'row count {len(parsed)} != 350')
if len(set(listed))!=350: errors.append('input paths are not unique')
if Counter(r.get('source_path') for r in parsed)!=Counter(listed): errors.append('output source paths differ from input')
for i,(row,source,rel) in enumerate(zip(parsed,paths,listed),1):
    req={'record_type','id','source_path','source_sha256','exact_unicode_slice','slice_start','slice_end','slice_sha256','scope','evidence_type','confidence','status'}
    miss=req-row.keys()
    if miss: errors.append(f'row {i}: missing {sorted(miss)}'); continue
    raw=source.read_bytes(); text=raw.decode('utf-8'); q=row['exact_unicode_slice']; s=row['slice_start']; e=row['slice_end']
    if Path(row['source_path']).is_absolute() or '..' in Path(row['source_path']).parts: errors.append(f'row {i}: path not relative')
    if row['source_path']!=rel: errors.append(f'row {i}: wrong path')
    if not isinstance(s,int) or not isinstance(e,int) or not isinstance(q,str) or s<0 or e<s or e>len(text) or text[s:e]!=q: errors.append(f'row {i}: Unicode slice mismatch')
    if row['source_sha256']!=hashlib.sha256(raw).hexdigest(): errors.append(f'row {i}: source hash mismatch')
    if row['slice_sha256']!=hashlib.sha256(q.encode('utf-8')).hexdigest(): errors.append(f'row {i}: slice hash mismatch')
    if row['status']!='candidate': errors.append(f'row {i}: status')
    if row['record_type']=='claim_candidate' and not row.get('claim'): errors.append(f'row {i}: claim missing')
    if row['record_type']=='source_note' and row['evidence_type']!='source_note': errors.append(f'row {i}: source note type')
after={p:hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}; changed=[str(p) for p in paths if before[p]!=after[p]]
if changed: errors.append(f'raw changed: {len(changed)}')
ct=Counter(r['record_type'] for r in parsed); et=Counter(r['evidence_type'] for r in parsed); st=Counter(r['scope'] for r in parsed)
report=f'''# تقرير unclaimed_4

## النطاق

- قائمة الإدخال: `{chunk}`.
- عدد المسارات المقروءة: **{len(paths)}**.
- عدد المسارات الفريدة: **{len(set(listed))}**.
- المصدر الوحيد للمادة: الملفات المدرجة تحت `raw/new/`.
- ملفات `raw/` المعدلة: **{len(changed)}**.
- المخرج: `{out}`، سجل واحد لكل مسار.

## الأعداد

- إجمالي سجلات JSONL: **{len(parsed)}**.
- `claim_candidate`: **{ct.get('claim_candidate',0)}**.
- `source_note`: **{ct.get('source_note',0)}**.

### نوع الدليل

'''+''.join(f'- `{k}`: **{v}**\n' for k,v in sorted(et.items()))+'''\n### النطاق\n\n'''+''.join(f'- `{k}`: **{v}**\n' for k,v in sorted(st.items()))+f'''\n\n## عقد السجل والتحقق

كل سجل يتضمن `source_path` نسبياً بالنسبة إلى جذر الويكي، و`source_sha256` للملف، و`exact_unicode_slice`، و`slice_start`/`slice_end` بوحدات Unicode code points (zero-based, end-exclusive)، و`slice_sha256` للمقطع UTF-8، و`scope`، و`evidence_type`، و`confidence`، و`status: candidate`.

- JSON صالح: **{len(parsed)}/{len(paths)}**.
- تطابق قائمة المسارات مع السجلات: **{'PASS' if Counter(r.get('source_path') for r in parsed)==Counter(listed) else 'FAIL'}**.
- مطابقة المقطع مع المصدر والإحداثيات: **{'PASS' if not errors else 'FAIL'}**.
- مطابقة hash الملف والمقطع: **{'PASS' if not errors else 'FAIL'}**.
- سلامة `raw/`: **{'PASS' if not changed else 'FAIL'}**.
- أخطاء التحقق: **{len(errors)}**.

المطالبات المرشحة محافظة ومحصورة في سياق المصدر؛ لا تعني `candidate` اعتماداً معرفياً أو تحققاً خارجياً. الملف القصير الوحيد حُفظ كـ`source_note` بدلاً من اختلاق Claim.
'''
if errors: report+='\n## الأخطاء\n\n'+'\n'.join(f'- {e}' for e in errors)+'\n'
report_path.write_text(report,encoding='utf-8')
print(json.dumps({'paths':len(paths),'rows':len(parsed),'record_types':dict(ct),'evidence_types':dict(et),'raw_changed':len(changed),'errors':len(errors)},ensure_ascii=False,indent=2))
if errors: raise SystemExit(1)
